import{_ as o,r as s,o as p,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"导航 - October CMS - 3.x","titleTemplate":false,"description":"了解如何在后台面板中添加新的菜单项。","frontmatter":{"subtitle":"了解如何在后台面板中添加新的菜单项。"},"headers":[{"level":2,"title":"导航计数器","slug":"导航计数器","link":"#导航计数器","children":[]},{"level":2,"title":"项目显示类型","slug":"项目显示类型","link":"#项目显示类型","children":[]},{"level":2,"title":"扩展后台菜单","slug":"扩展后台菜单","link":"#扩展后台菜单","children":[]}],"relativePath":"3.x/zh-cn/extend/backend/navigation.md","filePath":"3.x/zh-cn/extend/backend/navigation.md"}'),r={name:"3.x/zh-cn/extend/backend/navigation.md"};function u(g,n,d,k,m,h){const t=s("pre-heading"),e=s("post-heading");return p(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"导航",-1)),a(e),n[1]||(n[1]=i(`<p>插件可以通过在<a href="./../extending.html">插件注册文件</a>中覆盖 <code>registerNavigation</code> 方法来扩展后台导航菜单。本节展示如何向后台导航区域添加菜单项。以下是注册一个顶级导航菜单项和两个子菜单项的示例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerNavigation</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;blog&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-pencil&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>

            <span class="token string single-quoted-string">&#39;sideMenu&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Posts&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-copy&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;categories&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Categories&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-copy&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>注册后台导航时，您可以为 <code>label</code> 值使用<a href="./../system/localization.html">本地化字符串</a>。后台导航也可以通过 <code>permissions</code> 值进行控制，并对应已定义的<a href="./permissions.html">后台用户权限</a>。后台导航在整体导航菜单项中的显示顺序由 <code>order</code> 值控制。较高的数字意味着该项目将在菜单项顺序中更靠后显示，而较低的数字意味着它将更靠前显示。</p><p>要使子菜单项可见，您可以使用 <code>BackendMenu::setContext</code> 方法在<a href="./../system/controllers.html">后台控制器</a>中设置导航上下文。这将使父菜单项变为活动状态，并在侧边菜单中显示子项。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>指定菜单标签本地化字符串键，必需。</td></tr><tr><td><strong>order</strong></td><td>确定显示顺序时的数值权重。</td></tr><tr><td><strong>icon</strong></td><td><a href="./../../element/available-icons.html">October CMS 图标集合</a>中的图标名称，可选。</td></tr><tr><td><strong>iconSvg</strong></td><td>用于替代标准图标的 SVG 图标，SVG 图标应为矩形且可支持颜色，可选。</td></tr><tr><td><strong>url</strong></td><td>菜单项应指向的 URL（例如 <code>Backend::url(&#39;author/plugin/controller/action&#39;)</code>），必需。</td></tr><tr><td><strong>counter</strong></td><td>在菜单图标旁输出的数值。该值应为数字或返回数字的可调用对象，可选。</td></tr><tr><td><strong>counterLabel</strong></td><td>描述 counter 中数值引用的字符串值，可选。</td></tr><tr><td><strong>attributes</strong></td><td>应用于菜单项的属性和值的关联数组，可选。</td></tr><tr><td><strong>permissions</strong></td><td>后台用户查看菜单项所需的权限数组（注意：直接访问 URL 仍需要单独的权限检查），可选。</td></tr><tr><td><strong>sideMenu</strong></td><td>与父菜单项共享相同配置的子菜单项数组，可选。</td></tr><tr><td><strong>itemType</strong></td><td>指定项目的显示类型，仅限子菜单项。支持的值：<code>primary</code>、<code>link</code>、<code>ruler</code>、<code>section</code>。默认值：<code>link</code>。</td></tr></tbody></table></div><p>以下是系统生成的值，在注册导航项时不提供。</p><div class="table"><table tabindex="0"><thead><tr><th>键</th><th>描述</th></tr></thead><tbody><tr><td><strong>code</strong></td><td>作为该菜单选项唯一标识符的字符串值。</td></tr><tr><td><strong>owner</strong></td><td>以 &quot;Author.Plugin&quot; 格式指定菜单项所属插件或模块的字符串值。</td></tr></tbody></table></div><h2 id="导航计数器"><a href="#导航计数器" class="header-anchor">#</a> 导航计数器</h2><p>导航项支持指定计数器以表示有需要注意的项目。这些属性对父菜单项和子菜单项都可用。使用 <strong>counter</strong> 和 <strong>counterLabel</strong> 显示数字计数器。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;blog&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token comment">// ...</span>
    <span class="token string single-quoted-string">&#39;counter&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>MyMenuCounterService</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;getCounterMethod&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;counterLabel&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Label describing a dynamic menu counter&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="项目显示类型"><a href="#项目显示类型" class="header-anchor">#</a> 项目显示类型</h2><p>子菜单项支持使用 <code>itemType</code> 属性设置不同的显示类型，包括用户界面元素。将类型设置为 <code>section</code> 可显示导航分区。在键名前添加下划线（<code>_</code>）是表明它是 UI 元素的好方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;_section1&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;itemType&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;section&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Advanced&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>将分区与其上方的导航分隔线结合使用可能很有用。将类型设置为 <code>ruler</code> 可显示分隔线。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;_ruler1&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;itemType&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ruler&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>要显示行动号召，将类型设置为 <code>primary</code> 可将链接显示为主按钮。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;people_create&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;New Person&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-plus&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/people/create&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;itemType&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;primary&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="扩展后台菜单"><a href="#扩展后台菜单" class="header-anchor">#</a> 扩展后台菜单</h2><p><code>backend.menu.extendItems</code> <a href="./../extending.html">事件监听器</a>可用于在系统和插件注册导航项后修改现有的导航项。事件返回一个导航 <code>$manager</code> 实例，支持以下方法。</p><div class="table"><table tabindex="0"><thead><tr><th>方法</th><th>描述</th></tr></thead><tbody><tr><td><strong>addMainMenuItems($owner, $definitions)</strong></td><td>添加或更新主菜单定义</td></tr><tr><td><strong>getMainMenuItem($owner, $code)</strong></td><td>获取现有主菜单定义</td></tr><tr><td><strong>removeMainMenuItem($owner, $code)</strong></td><td>删除现有主菜单定义</td></tr><tr><td><strong>addSideMenuItems($owner, $code, $definitions)</strong></td><td>添加或更新侧边菜单定义</td></tr><tr><td><strong>getSideMenuItem($owner, $code, $sideCode)</strong></td><td>获取现有侧边菜单定义</td></tr><tr><td><strong>removeSideMenuItem($owner, $code, $sideCode)</strong></td><td>删除现有侧边菜单定义</td></tr></tbody></table></div><p>获取菜单项时，对象支持方法链以更新其属性。以下示例将编辑器的标签替换为 <strong>Code Editor</strong>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.menu.extendItems&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$manager</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">getMainMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;October.Editor&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;editor&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">label</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Code Editor&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>下一个示例将 Acme Blog 插件的标签更改为 <strong>News</strong> 并添加 <strong>9</strong> 计数器。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.menu.extendItems&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$manager</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">getMainMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">getSideMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">label</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;News&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">counter</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>同样，我们可以使用相同的事件移除菜单项。以下示例将分别移除所有项、移除单个项和移除多个项。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.menu.extendItems&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$manager</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">removeMainMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">removeSideMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">removeSideMenuItems</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;categories&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,26))])}const v=o(r,[["render",u]]);export{b as __pageData,v as default};
